import { initTRPC } from '@trpc/server';
import { createHTTPServer } from '@trpc/server/adapters/standalone';
import { z } from 'zod';

const t = initTRPC.create();

const publicProcedure = t.procedure;

const appRouter = t.router({
  countdown: publicProcedure
    .input(z.number())
    .subscription(async function* (opts) {
      const { input } = opts;
      for (let i = input; i >= 0; i--) {
        await new Promise<void>((resolve) => setTimeout(resolve, 100));
        yield i;
      }
    }),
});

export type AppRouter = typeof appRouter;

const server = createHTTPServer({
  router: appRouter,
  createContext: () => ({}),
});

server.listen(3000);

console.log('tRPC server listening on http://localhost:3000');

import { createTRPCClient, httpSubscriptionLink } from '@trpc/client';
import type { AppRouter } from './server';
import * as fs from 'node:fs/promises';

const client = createTRPCClient<AppRouter>({
  links: [
    httpSubscriptionLink({
      url: 'http://localhost:3000',
    }),
  ],
});

async function main() {
  const collected: number[] = [];
  const subscription = client.countdown.subscribe(5, {
    onData: (value: number) => {
      collected.push(value);
    },
    onError: (err: unknown) => {
      console.error('Subscription error:', err);
      process.exit(1);
    },
  });

  await new Promise<void>((resolve) => {
    subscription.unsubscribe();
    // Wait a bit longer than 6 * 100ms = 600ms to ensure full stream is received
    setTimeout(resolve, 1500);
  });

  // Re-subscribe since unsubscribe cuts off data collection. Actually let's iterate through asyncIterator instead.
}

// Use the asyncIterator pattern instead, which is cleaner for awaiting stream completion
async function main2() {
  const collected: number[] = [];
  const stream = client.countdown.subscribe(5, {
    onError: (err: unknown) => {
      console.error('Subscription error:', err);
      process.exit(1);
    },
  });

  // Use async iteration
  for await (const value of stream) {
    collected.push(value);
  }

  await fs.writeFile(
    '/home/user/project/output.json',
    JSON.stringify(collected),
  );
  console.log('Wrote output.json:', collected);
}

main2().catch((err) => {
  console.error('Error:', err);
  process.exit(1);
});

import { createTRPCClient, httpSubscriptionLink } from '@trpc/client';
import type { AppRouter } from './server';
import * as fs from 'node:fs/promises';

const client = createTRPCClient<AppRouter>({
  links: [
    httpSubscriptionLink({
      url: 'http://localhost:3000',
    }),
  ],
});

async function main() {
  const collected: number[] = [];

  const subscription = client.countdown.subscribe(5, {
    onError: (err: unknown) => {
      console.error('Subscription error:', err);
      process.exit(1);
    },
  });

  // Use async iteration to consume the stream; loop ends when server completes.
  for await (const value of subscription) {
    collected.push(value);
  }

  await fs.writeFile(
    '/home/user/project/output.json',
    JSON.stringify(collected),
  );
  console.log('Wrote output.json:', collected);
}

main().catch((err) => {
  console.error('Error:', err);
  process.exit(1);
});

