import { createTRPCClient, httpSubscriptionLink } from '@trpc/client';
import type { AppRouter } from './server';

const client = createTRPCClient<AppRouter>({
  links: [
    httpSubscriptionLink({
      url: 'http://localhost:3000',
    }),
  ],
});

async function main() {
  const collected: number[] = [];

  await new Promise<void>((resolve, reject) => {
    client.countdown.subscribe(5, {
      onData: (value: number) => {
        console.log('Got data:', value);
        collected.push(value);
      },
      onError: (err: unknown) => {
        console.error('Subscription error:', err);
        if (err && typeof err === 'object') {
          console.error('err.cause:', (err as any).cause);
          if ((err as any).cause?.error) {
            console.error('inner error:', (err as any).cause.error);
          }
          if ((err as any).cause?.suppressed) {
            console.error('suppressed:', (err as any).cause.suppressed);
          }
        }
        reject(err);
      },
      onComplete: () => {
        console.log('Subscription complete');
        resolve();
      },
    });
  });

  console.log('Collected:', collected);
}

main().catch((err) => {
  console.error('Error:', err);
  process.exit(1);
});

